const ocrData = $json;
const text = ocrData.ParsedResults?.[0]?.ParsedText || "";
const exitCode = ocrData.OCRExitCode;
const errorMsg = ocrData.ErrorMessage || "";

// 1. Check for engine errors (Error 99 etc)
if (exitCode !== 1 && exitCode !== 2) {
  return {
    json: {
      ocr_error: true,
      error_details: errorMsg || "The file could not be parsed. Possible corruption or invalid format."
    }
  };
}

const t = text.replace(/\r/g, "\n");
const lines = t.split("\n").map(l => l.trim()).filter(Boolean);
const upperText = t.toUpperCase();

// -------- ROLL NUMBER (12-digit normalization) --------
let roll_number = "Not Detected";

// Extract ALL digit sequences
const digitSequences = t.match(/\d+/g) || [];

let candidates = [];

// collect possible 12-digit combinations
digitSequences.forEach(seq => {
  if (seq.length === 12) {
    candidates.push(seq);
  }
  if (seq.length > 12) {
    for (let i = 0; i <= seq.length - 12; i++) {
      candidates.push(seq.substring(i, i + 12));
    }
  }
});

// Remove leading OCR garbage zeros
candidates = candidates.map(c => c.replace(/^0+/, ""));

// Prefer AU pattern (starts with 3 and length 12)
let valid = candidates.find(c => c.startsWith("3") && c.length === 12);

if (!valid && candidates.length > 0) {
  valid = candidates[0];
}

if (valid) roll_number = valid;
// -------- PROGRAM EXTRACTION --------
let program = "Not Detected";

if (/B\.?\s*TECH/i.test(t) || /BACHELOR OF TECHNOLOGY/i.test(t)) {

  if (/COMPUTER\s*SCIENCE/i.test(t) || /CSE/i.test(t))
    program = "B.Tech CSE";

  else if (/MECHANICAL/i.test(t))
    program = "B.Tech Mechanical";

  else if (/ELECTRICAL/i.test(t) || /EEE/i.test(t))
    program = "B.Tech Electrical";

  else if (/ELECTRONICS/i.test(t) || /ECE/i.test(t))
    program = "B.Tech ECE";

  else
    program = "B.Tech";
}
// -------- SEMESTER --------
let semester = "Not Detected";
// Only match if it looks like a semester (1st digit 1-8, 2nd digit 1-4)
const semMatch = t.match(/([1-8])-([1-4])/) || t.match(/YEAR ([1-4]) SEMESTER ([1-2])/i) || t.match(/([1-8])\/([1-4])/);
if (semMatch) {
  if (semMatch[0].includes("-") || semMatch[0].includes("/")) {
    semester = semMatch[0];
  } else {
    semester = `${semMatch[1]}-${semMatch[2]}`;
  }
}

// -------- NAME EXTRACTION --------
let name = "Not Detected";
let startIndex = lines.findIndex(l => l.toUpperCase().includes("A.U. COLLEGE OF ENGINEERING"));
if (startIndex !== -1) {
  for (let i = startIndex + 1; i < Math.min(lines.length, startIndex + 15); i++) {
    const cleaned = lines[i].replace(/[^A-Z\s]/gi, "").trim().toUpperCase();
    if (cleaned.split(/\s+/).length < 2 || cleaned.length < 8) continue;

    const badWords = ["UNIVERSITY", "COLLEGE", "MEMORANDUM", "ENGINEERING", "OFFICIAL", "OFFICE"];
    if (badWords.some(w => cleaned.includes(w))) continue;

    name = cleaned;
    break;
  }
}

return {
  json: {
    name,
    roll_number,
    program,
    semester,
    ocr_error: false
  }
};

const ocr = $items("Extract_OCR_Fields")[0].json;
const webhook = $items("Webhook")[0].json.body || {};

if (ocr.ocr_error) {
  return {
    json: {
      status: "failed",
      confidence: 0,
      reason: "OCR failed to read certificate"
    }
  };
}

const dbRows = $items("Fetch_Student_Record");

if (!dbRows || dbRows.length === 0 || !dbRows[0].json) {
  return {
    json: {
      status: "fake",
      confidence: 0.1,
      reason: `Roll number ${ocr.roll_number} not found in registry`
    }
  };
}

const db = dbRows[0].json;

let score = 0;
let checks = [];

// Roll number
if (String(ocr.roll_number) === String(db.roll_number)) {
  score += 2;
  checks.push("Roll number confirmed");
}

// Student Name Validation (OCR vs DB vs Form Input)
const formName = webhook.name || "";
let nameMatched = false;
if (ocr.name && db.name) {
  const ocrWords = ocr.name.toUpperCase().split(/\s+/);
  const dbWords = db.name.toUpperCase().split(/\s+/);
  const matches = ocrWords.filter(w => dbWords.some(d => d.includes(w) || w.includes(d)));

  if (matches.length >= 2) {
    nameMatched = true;
  }
}
if (formName && db.name) {
  const formWords = formName.toUpperCase().split(/\s+/);
  const dbWords = db.name.toUpperCase().split(/\s+/);
  const formMatches = formWords.filter(w => dbWords.some(d => d.includes(w) || w.includes(d)));
  if (formMatches.length >= Math.min(2, formWords.length)) {
     nameMatched = true;
  }
}
if (nameMatched) {
  score += 1;
  checks.push("Student name confirmed");
}

// Program / Degree Validation
const formDegree = webhook.degree_name || "";
let degreeMatched = false;
if (ocr.program && db.program && ocr.program.toUpperCase().includes(db.program.toUpperCase())) {
  degreeMatched = true;
}
if (formDegree && db.program && formDegree.toUpperCase().includes(db.program.toUpperCase())) {
  degreeMatched = true;
}
if (degreeMatched) {
  score += 1;
  checks.push("Program confirmed");
}

// LinkedIn Validation (Optional Bonus)
if (webhook.linkedin && webhook.linkedin.includes("linkedin.com/in/")) {
   checks.push("LinkedIn profile provided");
   score += 0.5;
}

let status = "fake";
let confidence = score / 4.5; // Adjusted max score
if (confidence > 1) confidence = 1.0;

if (score >= 3.5) status = "verified";
else if (score >= 2) status = "unclear";

return {
  json: {
    status,
    confidence: parseFloat(confidence.toFixed(2)),
    reason: checks.join(" | ")
  }
};

